// Tests of resizing on images like the ones of real use cases, all derived from testdata/photo.jpg
// (768x512). testdata/gen.go generates the files; the CMYK and large images are generated by the
// tests, since they are large.

// readTestdata returns the content of the file name of testdata.
func readTestdata(t *testing.T, name string) []byte {
	t.Helper()

	data, err := os.ReadFile(filepath.Join("testdata", name))
	if err != nil {
		t.Fatal(err)
	}

	return data
}

// toImage returns im as an image of the image package.
func toImage(t *testing.T, im *Image) image.Image {
	t.Helper()

	m, err := im.ToImage()
	if err != nil {
		t.Fatal(err)
	}

	return m
}

// iccProfile returns the ICC profile of im, or nil.
func iccProfile(im *Image) []byte {
	icc, _ := im.Get("icc-profile-data")
	b, _ := icc.([]byte)

	return b
}

// boxShrink returns the opaque 8-bit image m shrunk by f, each pixel being the average of f x f
// pixels: the reference of downscaling.
func boxShrink(m image.Image, f int) *image.NRGBA {
	r := m.Bounds()
	out := image.NewNRGBA(image.Rect(0, 0, r.Dx()/f, r.Dy()/f))
	n := uint32(f * f)
	for y := range out.Rect.Dy() {
		for x := range out.Rect.Dx() {
			var sum [3]uint32
			for j := range f {
				for i := range f {
					cr, cg, cb, _ := m.At(r.Min.X+x*f+i, r.Min.Y+y*f+j).RGBA()
					sum[0] += cr >> 8
					sum[1] += cg >> 8
					sum[2] += cb >> 8
				}
			}
			o := out.PixOffset(x, y)
			for c := range 3 {
				out.Pix[o+c] = uint8((sum[c] + n/2) / n)
			}
			out.Pix[o+3] = 0xff
		}
	}

	return out
}

// checkSize fails the test if im is not w x h.
func checkSize(t *testing.T, im *Image, w, h int) {
	t.Helper()

	if im.Width() != w || im.Height() != h {
		t.Errorf("got %dx%d, want %dx%d", im.Width(), im.Height(), w, h)
	}
}

func TestThumbnailSize(t *testing.T) {
	requireLibrary(t)
	landscape := testJPEG                           // 768x512
	portrait := readTestdata(t, "orientation6.jpg") // 768x512 displayed as 512x768

	tests := []struct {
		name          string
		data          []byte
		width, height int
		opts          Options
		w, h          int
	}{
		{"width", landscape, 300, 0, nil, 300, 200},
		{"height", landscape, 0, 300, nil, 450, 300},
		{"box", landscape, 300, 300, nil, 300, 200},
		{"enlarge", landscape, 1000, 0, nil, 1000, 667},
		{"size down", landscape, 1000, 0, Options{"size": SizeDown}, 768, 512},
		{"size up", landscape, 200, 0, Options{"size": SizeUp}, 768, 512},
		{"size force", landscape, 300, 100, Options{"size": SizeForce}, 300, 100},
		{"crop", landscape, 300, 300, Options{"crop": InterestingCentre}, 300, 300},
		{"crop none", landscape, 300, 0, Options{"crop": InterestingNone}, 300, 200},
		{"portrait width", portrait, 300, 0, nil, 300, 450},
		{"portrait height", portrait, 0, 300, nil, 200, 300},
		{"portrait box", portrait, 300, 300, nil, 200, 300},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			name := filepath.Join(t.TempDir(), "in.jpg")
			if err := os.WriteFile(name, tt.data, 0o644); err != nil {
				t.Fatal(err)
			}
			src := must(t)(LoadBuffer(tt.data, nil))

			for op, resize := range map[string]func() (*Image, error){
				"Thumbnail":       func() (*Image, error) { return Thumbnail(name, tt.width, tt.height, tt.opts) },
				"ThumbnailBuffer": func() (*Image, error) { return ThumbnailBuffer(tt.data, tt.width, tt.height, tt.opts) },
				"ThumbnailImage":  func() (*Image, error) { return src.ThumbnailImage(tt.width, tt.height, tt.opts) },
			} {
				t.Run(op, func(t *testing.T) {
					im := must(t)(resize())
					checkSize(t, im, tt.w, tt.h)
				})
			}
		})
	}

	for name, err := range map[string]error{
		"no size":        func() error { _, err := ThumbnailBuffer(landscape, 0, 0, nil); return err }(),
		"negative":       func() error { _, err := ThumbnailBuffer(landscape, -1, 100, nil); return err }(),
		"force one size": func() error { _, err := ThumbnailBuffer(landscape, 300, 0, Options{"size": "force"}); return err }(),
		"crop one size": func() error {
			_, err := ThumbnailBuffer(landscape, 0, 300, Options{"crop": InterestingAttention})
			return err
		}(),
		"image no size":   func() error { _, err := mustLoad(t).ThumbnailImage(0, 0, nil); return err }(),
		"file no size":    func() error { _, err := Thumbnail("in.jpg", 0, 0, nil); return err }(),
		"unknown options": func() error { _, err := ThumbnailBuffer(landscape, 10, 0, Options{"nope": 1}); return err }(),
	} {
		if err == nil || !strings.HasPrefix(err.Error(), "vips: ") {
			t.Errorf("%s: got error %v", name, err)
		}
	}

	// Every size is reached exactly, also with Resize given the ratio of the sizes.
	src := mustLoad(t)
	for w := 1; w <= 1600; w += 3 {
		h := w/2 + 1
		for _, tt := range []struct {
			name string
			op   func() (*Image, error)
			w, h int
		}{
			{"width", func() (*Image, error) { return src.ThumbnailImage(w, 0, nil) }, w, -1},
			{"height", func() (*Image, error) { return src.ThumbnailImage(0, h, nil) }, -1, h},
			{"force", func() (*Image, error) { return src.ThumbnailImage(w, h, Options{"size": SizeForce}) }, w, h},
			{"resize", func() (*Image, error) {
				return src.Resize(float64(w)/768, Options{"vscale": float64(h) / 512})
			}, w, h},
		} {
			im, err := tt.op()
			if err != nil {
				t.Fatalf("%s %dx%d: %v", tt.name, w, h, err)
			}
			if tt.w >= 0 && im.Width() != tt.w || tt.h >= 0 && im.Height() != tt.h {
				t.Errorf("%s %dx%d: got %dx%d", tt.name, tt.w, tt.h, im.Width(), im.Height())
			}
			im.Close()
		}
	}
}

func TestResizeQuality(t *testing.T) {
	src := mustLoad(t)
	photo := toImage(t, src)
	// Compared with the average of f x f pixels, a good resize has a PSNR of more than 41 dB, the
	// same resize shifted by one pixel less than 36 dB.
	const minPSNR = 39

	for _, f := range []int{2, 4} {
		want := boxShrink(photo, f)
		shifted := boxShrink(photo.(*image.RGBA).SubImage(image.Rect(1, 0, 768, 512)), f)
		w := 768 / f

		for name, resize := range map[string]func() (*Image, error){
			"Resize":          func() (*Image, error) { return src.Resize(1/float64(f), nil) },
			"Resize/lanczos3": func() (*Image, error) { return src.Resize(1/float64(f), Options{"kernel": KernelLanczos3}) },
			"ThumbnailBuffer": func() (*Image, error) { return ThumbnailBuffer(testJPEG, w, 0, nil) },
			"ThumbnailImage":  func() (*Image, error) { return src.ThumbnailImage(w, 0, nil) },
		} {
			got := toImage(t, must(t)(resize()))
			if p := psnr(want, got); p < minPSNR {
				t.Errorf("%s 1/%d: PSNR %.1f dB, want >= %d", name, f, p, minPSNR)
			}
			if p := psnr(shifted, got); p >= minPSNR {
				t.Errorf("%s 1/%d: PSNR with the shifted reference %.1f dB, want < %d", name, f, p, minPSNR)
			}
		}
	}

	// Enlarging and shrinking back gives the original image.
	for name, resize := range map[string]func() (*Image, error){
		"Resize":         func() (*Image, error) { return src.Resize(2, nil) },
		"ThumbnailImage": func() (*Image, error) { return src.ThumbnailImage(1536, 0, nil) },
	} {
		im := must(t)(resize())
		checkSize(t, im, 1536, 1024)
		if p := psnr(photo, boxShrink(toImage(t, im), 2)); p < 35 {
			t.Errorf("%s x2: PSNR %.1f dB, want >= 35", name, p)
		}
	}
}

func TestResizeAlpha(t *testing.T) {
	requireLibrary(t)
	// A white disk of radius 200 on a transparent black background, 512x512.
	data := readTestdata(t, "logo.png")
	logo := must(t)(LoadBuffer(data, nil))
	if logo.Bands() != 4 || !logo.HasAlpha() {
		t.Fatalf("logo.png: got %d bands", logo.Bands())
	}
	logo16 := must(t)(must(t)(must(t)(logo.Linear([]float64{257}, []float64{0}, nil)).Cast(BandFormatUshort, nil)).Copy(Options{"interpretation": InterpretationRGB16}))

	tests := []struct {
		name string
		op   func() (*Image, error)
		deep bool
	}{
		{"Resize", func() (*Image, error) { return logo.Resize(1.0/8, nil) }, false},
		{"Resize/linear", func() (*Image, error) { return logo.Resize(1.0/8, Options{"kernel": KernelLinear}) }, false},
		{"Resize/16-bit", func() (*Image, error) { return logo16.Resize(1.0/8, nil) }, true},
		{"ThumbnailBuffer", func() (*Image, error) { return ThumbnailBuffer(data, 64, 0, nil) }, false},
		{"ThumbnailImage", func() (*Image, error) { return logo.ThumbnailImage(64, 0, nil) }, false},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			im := must(t)(tt.op())
			checkSize(t, im, 64, 64)
			if !im.HasAlpha() {
				t.Fatalf("got %d bands without alpha", im.Bands())
			}

			m := toImage(t, im)
			if _, deep := m.(*image.NRGBA64); deep != tt.deep {
				t.Errorf("got %T", m)
			}

			// The colors of transparent pixels must not darken the edge of the disk.
			darkest, coverage := 1.0, 0.0
			for y := range 64 {
				for x := range 64 {
					r, g, b, a := m.At(x, y).RGBA()
					coverage += float64(a) / 0xffff
					if a > 0x1000 {
						darkest = min(darkest, float64(min(r, g, b))/float64(a))
					}
				}
			}
			if darkest < 0.98 {
				t.Errorf("darkest edge pixel: %.0f%% of white, want >= 98%%", darkest*100)
			}
			// The area of the disk is kept: pi * 25^2 pixels.
			if want := 3.14159 * 25 * 25; coverage < want*0.99 || coverage > want*1.01 {
				t.Errorf("coverage: got %.0f pixels, want %.0f", coverage, want)
			}
		})
	}

	// Resize premultiplies like the thumbnail operations: halving gives the same pixels.
	if p := psnr(toImage(t, must(t)(logo.ThumbnailImage(256, 0, nil))), toImage(t, must(t)(logo.Resize(0.5, nil)))); !math.IsInf(p, 1) {
		t.Errorf("Resize and ThumbnailImage: PSNR %.1f dB, want the same pixels", p)
	}
}

func TestResizeOrientation(t *testing.T) {
	src := mustLoad(t)
	// photo.jpg with an EXIF orientation of 6: displayed rotated by 90 degrees clockwise.
	data := readTestdata(t, "orientation6.jpg")
	stored := must(t)(LoadBuffer(data, nil))
	if o, err := stored.Get("orientation"); err != nil || o != 6 {
		t.Fatalf("orientation: got %v, %v", o, err)
	}
	checkSize(t, stored, 768, 512)
	want := toImage(t, must(t)(must(t)(src.Rot(AngleD90)).ThumbnailImage(300, 0, nil)))

	// The thumbnail operations rotate the image upright.
	for name, op := range map[string]func() (*Image, error){
		"ThumbnailBuffer": func() (*Image, error) { return ThumbnailBuffer(data, 300, 0, nil) },
		"ThumbnailImage":  func() (*Image, error) { return stored.ThumbnailImage(300, 0, nil) },
		"Autorot+Resize": func() (*Image, error) {
			upright := must(t)(stored.Autorot())
			return upright.Resize(300.0/512, nil)
		},
	} {
		t.Run(name, func(t *testing.T) {
			im := must(t)(op())
			checkSize(t, im, 300, 450)
			if p := psnr(want, toImage(t, im)); p < 40 {
				t.Errorf("PSNR with the rotated photo %.1f dB, want >= 40", p)
			}

			// The saved image is displayed the same way.
			buf, err := im.SaveBuffer(".jpg", nil)
			if err != nil {
				t.Fatal(err)
			}
			back := must(t)(LoadBuffer(buf, nil))
			checkSize(t, back, 300, 450)
			if o, err := back.Get("orientation"); err == nil && o != 1 {
				t.Errorf("saved orientation: got %v", o)
			}
		})
	}

	// Without rotation.
	checkSize(t, must(t)(ThumbnailBuffer(data, 300, 0, Options{"no_rotate": true})), 300, 200)
	resized := must(t)(stored.Resize(0.5, nil))
	checkSize(t, resized, 384, 256)
	if o, err := resized.Get("orientation"); err != nil || o != 6 {
		t.Errorf("Resize keeps the orientation: got %v, %v", o, err)
	}
}

func TestResizeColor(t *testing.T) {
	src := mustLoad(t)
	want := toImage(t, must(t)(ThumbnailBuffer(testJPEG, 384, 0, nil)))

	t.Run("CMYK", func(t *testing.T) {
		// CMYK JPEG with the CMYK profile of libvips embedded, like print images.
		cmyk := must(t)(callImage("icc_transform", nil, Options{"in": src, "output_profile": "cmyk"}))
		data, err := cmyk.SaveBuffer(".jpg", Options{"Q": 90})
		if err != nil {
			t.Fatal(err)
		}
		loaded := must(t)(LoadBuffer(data, nil))
		if loaded.Interpretation() != InterpretationCMYK || loaded.Bands() != 4 || len(iccProfile(loaded)) == 0 {
			t.Fatalf("got %s, %d bands, %d bytes of profile", loaded.Interpretation(), loaded.Bands(), len(iccProfile(loaded)))
		}

		// The thumbnail operations convert to sRGB.
		thumb := must(t)(ThumbnailBuffer(data, 384, 0, nil))
		if thumb.Interpretation() != InterpretationSRGB || thumb.Bands() != 3 {
			t.Errorf("thumbnail: got %s, %d bands", thumb.Interpretation(), thumb.Bands())
		}
		buf, err := thumb.SaveBuffer(".jpg", nil)
		if err != nil {
			t.Fatal(err)
		}
		back := must(t)(LoadBuffer(buf, nil))
		if back.Interpretation() != InterpretationSRGB || iccProfile(back) != nil {
			t.Errorf("saved: got %s with %d bytes of profile", back.Interpretation(), len(iccProfile(back)))
		}
		// Converting to CMYK and back loses colors out of the CMYK gamut.
		if p := psnr(want, toImage(t, back)); p < 28 {
			t.Errorf("PSNR with the sRGB photo %.1f dB, want >= 28", p)
		}

		// Resize keeps CMYK, ToImage converts to sRGB.
		resized := must(t)(loaded.Resize(0.5, nil))
		if resized.Interpretation() != InterpretationCMYK {
			t.Errorf("Resize: got %s", resized.Interpretation())
		}
		if p := psnr(want, toImage(t, resized)); p < 28 {
			t.Errorf("Resize: PSNR with the sRGB photo %.1f dB, want >= 28", p)
		}
	})

	t.Run("P3", func(t *testing.T) {
		// Display P3 JPEG with its profile embedded, like the photos of recent phones.
		data := readTestdata(t, "p3.jpg")
		p3 := iccProfile(must(t)(LoadBuffer(data, nil)))
		if len(p3) == 0 {
			t.Fatal("p3.jpg has no profile")
		}

		// By default the pixels stay in P3 and keep their profile, so that they are displayed with
		// the right colors.
		thumb := must(t)(ThumbnailBuffer(data, 384, 0, nil))
		buf, err := thumb.SaveBuffer(".jpg", nil)
		if err != nil {
			t.Fatal(err)
		}
		back := must(t)(LoadBuffer(buf, nil))
		if !bytes.Equal(iccProfile(back), p3) {
			t.Errorf("saved: got %d bytes of profile, want the P3 profile", len(iccProfile(back)))
		}
		kept := psnr(want, toImage(t, back))

		// output_profile converts to sRGB.
		srgb := must(t)(ThumbnailBuffer(data, 384, 0, Options{"output_profile": "srgb"}))
		if bytes.Equal(iccProfile(srgb), p3) {
			t.Error("output_profile srgb: got the P3 profile")
		}
		converted := psnr(want, toImage(t, srgb))
		if converted < 40 || kept >= converted-5 {
			t.Errorf("PSNR with the sRGB photo: %.1f dB converted to sRGB, %.1f dB kept in P3", converted, kept)
		}
	})
}

func TestResize16Bit(t *testing.T) {
	requireLibrary(t)
	// The photo halved in 16-bit precision, 384x256.
	data := readTestdata(t, "photo16.png")
	src := must(t)(LoadBuffer(data, nil))
	if src.Format() != BandFormatUshort || src.Interpretation() != InterpretationRGB16 {
		t.Fatalf("photo16.png: got %s %s", src.Format(), src.Interpretation())
	}
	want := boxShrink(toImage(t, src), 2)

	// Resize keeps 16 bits.
	resized := must(t)(src.Resize(0.5, nil))
	checkSize(t, resized, 192, 128)
	if resized.Format() != BandFormatUshort || resized.Interpretation() != InterpretationRGB16 {
		t.Errorf("Resize: got %s %s", resized.Format(), resized.Interpretation())
	}
	buf, err := resized.SaveBuffer(".png", nil)
	if err != nil {
		t.Fatal(err)
	}
	back := must(t)(LoadBuffer(buf, nil))
	m := toImage(t, back)
	if _, ok := m.(*image.RGBA64); !ok || back.Format() != BandFormatUshort {
		t.Errorf("saved PNG: got %s, %T", back.Format(), m)
	}
	if p := psnr(want, m); p < 39 {
		t.Errorf("Resize: PSNR %.1f dB, want >= 39", p)
	}

	// The thumbnail operations convert to 8 bits.
	thumb := must(t)(ThumbnailBuffer(data, 192, 0, nil))
	if thumb.Format() != BandFormatUchar || thumb.Interpretation() != InterpretationSRGB {
		t.Errorf("ThumbnailBuffer: got %s %s", thumb.Format(), thumb.Interpretation())
	}
	if p := psnr(want, toImage(t, thumb)); p < 39 {
		t.Errorf("ThumbnailBuffer: PSNR %.1f dB, want >= 39", p)
	}
}

func TestResizeAnimated(t *testing.T) {
	requireLibrary(t)

	// 4 frames of 160x120.
	for _, name := range []string{"anim.gif", "anim.webp"} {
		t.Run(name, func(t *testing.T) {
			data := readTestdata(t, name)
			suffix := filepath.Ext(name)

			// checkFrames checks that im has 4 frames of 80x60.
			checkFrames := func(t *testing.T, im *Image) {
				t.Helper()

				checkSize(t, im, 80, 240)
				pageHeight, err := im.Get("page-height")
				if err != nil || pageHeight != 60 {
					t.Errorf("page-height: got %v, %v", pageHeight, err)
				}
				first := toImage(t, must(t)(im.ExtractArea(0, 0, 80, 60)))
				last := toImage(t, must(t)(im.ExtractArea(0, 180, 80, 60)))
				if p := psnr(first, last); p > 25 {
					t.Errorf("the first and last frames look the same: PSNR %.1f dB", p)
				}
			}

			// All the frames are resized with the loader option n=-1.
			thumb := must(t)(ThumbnailBuffer(data, 80, 0, Options{"option_string": "n=-1"}))
			checkFrames(t, thumb)
			buf, err := must(t)(thumb.CopyMemory()).SaveBuffer(suffix, nil)
			if err != nil {
				t.Fatal(err)
			}
			back := must(t)(LoadBuffer(buf, Options{"n": -1}))
			checkFrames(t, back)
			if pages, err := back.Get("n-pages"); err != nil || pages != 4 {
				t.Errorf("saved n-pages: got %v, %v", pages, err)
			}

			frames := must(t)(LoadBuffer(data, Options{"n": -1}))
			checkFrames(t, must(t)(frames.ThumbnailImage(80, 0, nil)))
			if _, err := frames.Resize(0.5, nil); err == nil || !strings.Contains(err.Error(), "ThumbnailImage") {
				t.Errorf("Resize: got error %v", err)
			}

			// Without n=-1, only the first frame.
			checkSize(t, must(t)(ThumbnailBuffer(data, 80, 0, nil)), 80, 60)
		})
	}
}

func TestResizeLarge(t *testing.T) {
	src := mustLoad(t)

	// A 6144x4096 (25 Mpx) JPEG, like the photos of cameras.
	start := time.Now()
	large, err := must(t)(src.Resize(8, nil)).SaveBuffer(".jpg", Options{"Q": 85})
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("6144x4096 JPEG: %d bytes, %v", len(large), time.Since(start))

	want := toImage(t, must(t)(ThumbnailBuffer(testJPEG, 300, 0, nil)))
	start = time.Now()
	thumb := must(t)(ThumbnailBuffer(large, 300, 0, nil))
	got := toImage(t, thumb)
	t.Logf("thumbnail: %v", time.Since(start))
	checkSize(t, thumb, 300, 200)
	if p := psnr(want, got); p < 30 {
		t.Errorf("PSNR with the thumbnail of the small photo %.1f dB, want >= 30", p)
	}

	// Loading with sequential access does not keep the whole image in memory.
	loaded := must(t)(LoadBuffer(large, Options{"access": "sequential"}))
	resized := must(t)(loaded.Resize(0.125, nil))
	checkSize(t, resized, 768, 512)
	if p := psnr(toImage(t, src), toImage(t, resized)); p < 30 {
		t.Errorf("Resize: PSNR with the small photo %.1f dB, want >= 30", p)
	}
}

func TestCopyMemory(t *testing.T) {
	requireLibrary(t)

	// The results of Thumbnail and ThumbnailBuffer are computed in memory: they can be saved in
	// several formats, and the images computed from them use all the threads.
	thumb := must(t)(ThumbnailBuffer(testJPEG, 200, 0, nil))
	checkSaves(t, thumb, 200, 133)
	if _, err := thumb.Get(metaConcurrency); err == nil {
		t.Errorf("ThumbnailBuffer: the result has the field %q", metaConcurrency)
	}

	// An image loaded with the sequential access is computed while the JPEG is read, once only;
	// its copy in memory can be saved several times.
	loaded := must(t)(LoadBuffer(testJPEG, Options{"access": "sequential"}))
	checkSaves(t, must(t)(loaded.CopyMemory()), 768, 512)
}

// checkSaves checks that im of size w x h can be saved in several formats.
func checkSaves(t *testing.T, im *Image, w, h int) {
	t.Helper()

	for _, suffix := range []string{".jpg", ".png", ".webp", ".jpg"} {
		buf, err := im.SaveBuffer(suffix, nil)
		if err != nil {
			t.Fatal(err)
		}
		checkSize(t, must(t)(LoadBuffer(buf, nil)), w, h)
	}
	toImage(t, im)
}
